DECLARE
    v_count NUMBER := 0;
BEGIN
    SELECT COUNT(1)
      INTO v_count
      FROM user_tables
     WHERE table_name = 'FMP_PAGE_CONFIG';

    IF v_count = 0 THEN
        EXECUTE IMMEDIATE q'[
            CREATE TABLE "FMP_PAGE_CONFIG"
            (
                "CONFIG_ID"      NUMBER(20, 0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999
                    INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE NOT NULL ENABLE,
                "SYSTEM_ID"      NUMBER(20, 0)                                                         NOT NULL ENABLE,
                "TENANT_ID"      NUMBER(20, 0)                                                         NOT NULL ENABLE,
                "PAGE_ID"        NUMBER(20, 0)                                                         NOT NULL ENABLE,
                "IS_VISIBLE"     NUMBER(1, 0) DEFAULT 1                                                NOT NULL ENABLE,
                "CREATED_BY"     NUMBER(20, 0)                                                         NOT NULL ENABLE,
                "CREATION_DATE"  DATE         DEFAULT SYSDATE                                          NOT NULL ENABLE,
                "UPDATED_BY"     NUMBER(20, 0)                                                         NOT NULL ENABLE,
                "UPDATE_DATE"    DATE         DEFAULT SYSDATE                                          NOT NULL ENABLE,
                "DEL_FLAG"       NUMBER(1, 0) DEFAULT 0                                                NOT NULL ENABLE,
                PRIMARY KEY ("CONFIG_ID")
                    USING INDEX ENABLE
            )
        ]';
    END IF;
END;
/
